export function mergeIntervals(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError('Input must be an array');
  }
  const merged = [];
  for (const interval of intervals) {
    if (!Array.isArray(interval) || interval.length !== 2 || typeof interval[0] !== 'number' || typeof interval[1] !== 'number' || interval[0] > interval[1]) {
      throw new TypeError('Invalid interval');
    }
    const [start, end] = interval;
    if (merged.length === 0 || merged[merged.length - 1][1] < start) {
      merged.push([start, end]);
    } else {
      const last = merged[merged.length - 1];
      last[1] = Math.max(last[1], end);
    }
  }
  return merged;
}
