export function safeJoinPath(base, userPath) {
  if (typeof base !== 'string' || typeof userPath !== 'string') {
    throw new TypeError('Both base and userPath must be strings');
  }

  if (!base.startsWith('/')) {
    throw new Error('Base must be an absolute path');
  }

  const baseDir = base.replace(/\/$/, '');
  const userPathParts = userPath.split(/\/|\\/);
  const result = [];

  for (const part of userPathParts) {
    if (part === '..') {
      if (result.length === 0 || result[result.length - 1] !== baseDir) {
        throw new Error('Cannot climb above base');
      }
      result.pop();
    } else if (part === '' || part === '.') {
      continue;
    } else if (part === '%2e' || part === '%2f' || part === '%5c') {
      throw new Error('Percent-encoded dots or slashes are not allowed');
    } else if (part === '\x00') {
      throw new Error('NUL bytes are not allowed');
    } else {
      result.push(part);
    }
  }

  return base + '/' + result.join('/');
}
