      } else if (line[i] === '\r' && i + 1 < line.length && line[i + 1] === '\n') {
        currentRow.push(currentField);
        currentField = '';
        i += 2;
      } else {
        currentField += line[i];
        i++;
      }
    }
    if (inQuote) {
      throw new Error('Unclosed quote');
    }
    currentRow.push(currentField);
    if (currentField) {
      result.push(currentRow);
      currentRow = [];
    }
  }
