export function evalArithmetic(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const tokens = text.match(/-?\d+(?:\.\d+)?|[-+*/^()]/g);
  if (!tokens) {
    throw new SyntaxError('Invalid input');
  }

  const precedence = {
    '^': 3,
    '*': 2,
    '/': 2,
    '+': 1,
    '-': 1,
  };

  const stack = [];
  const output = [];

  for (const token of tokens) {
    if (token === '(') {
      stack.push(token);
    } else if (token === ')') {
      while (stack[stack.length - 1] !== '(') {
        output.push(stack.pop());
      }
      stack.pop();
    } else if (precedence[token] !== undefined) {
      while (stack.length > 0 && stack[stack.length - 1] !== '(' && precedence[stack[stack.length - 1]] >= precedence[token]) {
        output.push(stack.pop());
      }
      stack.push(token);
    } else {
      output.push(token);
    }
  }

  if (stack.length > 0) {
    throw new SyntaxError('Unbalanced parentheses');
  }

  return output;
}

export function calculate(output) {
  let result = output[0];
  for (let i = 1; i < output.length; i += 2) {
    const operator = output[i];
    const operand = parseFloat(output[i + 1]);
    switch (operator) {
      case '+':
        result += operand;
        break;
      case '-':
        result -= operand;
        break;
      case '*':
        result *= operand;
        break;
      case '/':
        if (operand === 0) {
          throw new RangeError('Division by zero');
        }
        result /= operand;
        break;
      case '^':
        result = Math.pow(result, operand);
        break;
    }
  }
  return result;
}

export function evalArithmeticFinal(text) {
  const tokens = evalArithmetic(text);
  return calculate(tokens);
}
